#!/usr/bin/env python3
"""Merge user data from three sources with different schemas.

Priority: source_a > source_b > source_c
Outputs:
  /app/merged_users.parquet
  /app/conflicts.json
"""
import csv
import json
import os
import re
from datetime import datetime

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]
PRIORITY = ["source_a", "source_b", "source_c"]

FIELD_MAP = {
    # user_id
    "user_id": "user_id", "id": "user_id", "userid": "user_id", "uid": "user_id",
    # email
    "email": "email", "email_address": "email", "emailaddress": "email", "mail": "email",
    # name
    "full_name": "name", "name": "name", "username": "name", "user_name": "name",
    "fullname": "name", "display_name": "name",
    # created_date
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "created_date": "created_date", "join_date": "created_date", "signup_date": "created_date",
    "registered": "created_date", "joined_at": "created_date",
    # status
    "status": "status", "is_active": "status", "active": "status", "account_status": "status",
    "state": "status",
}
BOOL_STATUS_KEYS = {"is_active", "active"}
FIELDS = ["name", "email", "created_date", "status"]

DATE_FORMATS = [
    "%Y-%m-%d", "%Y/%m/%d", "%d/%m/%Y", "%m/%d/%Y", "%d-%m-%Y", "%m-%d-%Y",
    "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%SZ",
    "%d %b %Y", "%d %B %Y", "%b %d, %Y", "%B %d, %Y", "%Y%m%d",
]


def norm_key(k):
    k = str(k).strip()
    snake = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", k).lower()
    for cand in (k.lower(), snake, k.lower().replace("_", "").replace(" ", "")):
        if cand in FIELD_MAP:
            return FIELD_MAP[cand]
    return None


def norm_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, (datetime, pd.Timestamp)):
        return v.strftime("%Y-%m-%d")
    if hasattr(v, "strftime"):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null", "nat"):
        return None
    if re.fullmatch(r"\d{10}|\d{13}", s):
        ts = int(s)
        ts = ts / 1000 if len(s) == 13 else ts
        return datetime.utcfromtimestamp(ts).strftime("%Y-%m-%d")
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    try:
        return pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s


def norm_status(v, raw_key=None):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if not s or s.lower() in ("nan", "none", "null"):
        return None
    low = s.lower()
    if raw_key in BOOL_STATUS_KEYS or low in ("true", "false", "1", "0", "yes", "no"):
        if low in ("true", "1", "yes", "t", "y"):
            return "active"
        if low in ("false", "0", "no", "f", "n"):
            return "inactive"
    return s


def norm_record(raw):
    out = {}
    for k, v in raw.items():
        field = norm_key(k)
        if field is None:
            continue
        if v is None:
            continue
        try:
            if pd.isna(v):
                continue
        except (TypeError, ValueError):
            pass
        if field == "user_id":
            try:
                out["user_id"] = int(str(v).strip())
            except (ValueError, TypeError):
                continue
        elif field == "created_date":
            d = norm_date(v)
            if d is not None:
                out["created_date"] = d
        elif field == "status":
            st = norm_status(v, str(k).strip().lower())
            if st is not None and "status" not in out:
                out["status"] = st
        else:
            s = str(v).strip()
            if s:
                out[field] = s
    return out if "user_id" in out else None


def load_json(path):
    with open(path) as f:
        data = json.load(f)
    if isinstance(data, dict):
        for key in ("users", "data", "records", "items"):
            if key in data and isinstance(data[key], list):
                data = data[key]
                break
        else:
            data = [data]
    return data


def load_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def load_parquet(path):
    df = pd.read_parquet(path)
    return df.to_dict("records")


def load(path):
    ext = os.path.splitext(path)[1].lower()
    if ext == ".json":
        return load_json(path)
    if ext in (".csv", ".tsv"):
        return load_csv(path)
    return load_parquet(path)


def main():
    by_source = {}
    order = []
    for name, path in SOURCES:
        recs = {}
        for raw in load(path):
            rec = norm_record(raw)
            if rec is None:
                continue
            uid = rec["user_id"]
            if uid not in recs:
                recs[uid] = rec
            else:
                recs[uid].update(rec)
            if uid not in order:
                order.append(uid)
        by_source[name] = recs

    merged = []
    conflicts = []
    for uid in sorted(order):
        present = [s for s in PRIORITY if uid in by_source[s]]
        row = {"user_id": uid}
        for field in FIELDS:
            values = {}
            for s in present:
                v = by_source[s][uid].get(field)
                if v is not None:
                    values[s] = v
            if not values:
                row[field] = None
                continue
            selected = next(values[s] for s in PRIORITY if s in values)
            row[field] = selected
            if len(set(values.values())) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {s: values[s] for s in PRIORITY if s in values},
                    "selected": selected,
                })
        merged.append(row)

    df = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for c in ("name", "email", "created_date", "status"):
        df[c] = df[c].astype(object).where(df[c].notna(), None)
    df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(df.to_string(index=False))
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

